css:
/* Oma's Mahjong — all styles.
   1 base · 2 buttons & chips · 3 home · 4 menu screens · 5 game screen · 6 tiles · 7 tray & tools
   8 pop-ups · 9 celebrations · 10 leaderboard & family · 11 tasks, stats, special tiles
   12 themes (Zonnebloem, high contrast) · 13 small screens */

/* ========== 1 base ========== */
@font-face { font-family: Nunito; font-weight: 700; src: url(fonts/nunito-latin-700-normal.woff2) format('woff2'); }
@font-face { font-family: Nunito; font-weight: 800; src: url(fonts/nunito-latin-800-normal.woff2) format('woff2'); }
@font-face { font-family: Nunito; font-weight: 900; src: url(fonts/nunito-latin-900-normal.woff2) format('woff2'); }

:root {
  --ink: #3b2a14;
  --cream: #fff8e8;
  --cream2: #f6e9c8;
  --gold: #ffc531;
  --gold-d: #d99a00;
  --green: #2bb673;
  --green-d: #178a52;
  --orange: #ff8a3d;
  --orange-d: #d9621a;
  --blue: #3d9cf5;
  --blue-d: #1f6fc2;
  --pink: #ff6fa3;
  --pink-d: #d1477c;
  --muted: #8a7448;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bot: env(safe-area-inset-bottom, 0px);
}
* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }
html, body { margin: 0; height: 100%; overflow: hidden; background: #0b4d3c; }
body { font-family: Nunito, 'Segoe UI', Roboto, Arial, sans-serif; font-weight: 800; color: var(--ink); touch-action: manipulation; }
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; padding: 0; }

#bg { position: fixed; inset: 0; transition: background .6s; }
#bg::after { /* soft vignette + subtle pattern so every background feels like a table */
  content: ''; position: absolute; inset: 0;
  background:
    radial-gradient(circle at 50% 35%, transparent 40%, rgba(0,0,0,.28) 100%),
    repeating-linear-gradient(45deg, rgba(255,255,255,.035) 0 2px, transparent 2px 14px);
}
#app { position: fixed; inset: 0; padding-top: var(--safe-top); padding-bottom: var(--safe-bot); }
.screen { position: absolute; inset: var(--safe-top) 0 var(--safe-bot) 0; display: none; flex-direction: column; }
.screen.active { display: flex; animation: fadeIn .25s ease; }
@keyframes fadeIn { from { opacity: 0; } }
@keyframes pop { from { transform: scale(.6); opacity: 0; } }
@keyframes pulse { 50% { transform: scale(1.03); } }
@keyframes bob { 50% { translate: 0 -6px; } }
@keyframes spin { to { transform: rotate(360deg); } }

/* ========== 2 buttons & chips ========== */
.chip { background: rgba(0,0,0,.28); color: #fff; border-radius: 999px; padding: 6px 14px; font-weight: 900; font-size: 18px; white-space: nowrap; box-shadow: inset 0 -2px 0 rgba(0,0,0,.2); }
.big-chip { font-size: 22px; padding: 8px 18px; }
.icon-btn { width: 52px; height: 52px; border-radius: 16px; background: var(--cream); font-size: 26px; display: grid; place-items: center; box-shadow: 0 5px 0 var(--cream2), 0 7px 10px rgba(0,0,0,.25); color: var(--ink); flex: none; }
.icon-btn:active { transform: translateY(4px); box-shadow: 0 1px 0 var(--cream2); }
.icon-btn.small { width: 44px; height: 44px; font-size: 26px; border-radius: 14px; }

.big-btn { position: relative; display: flex; align-items: center; gap: 16px; width: 100%; padding: 16px 20px; border-radius: 24px; color: #fff; text-align: left; text-shadow: 0 2px 0 rgba(0,0,0,.18); transition: transform .08s; }
.big-btn b { display: block; font-size: 30px; font-weight: 900; line-height: 1.05; }
.big-btn small { display: block; font-size: 18px; font-weight: 800; opacity: .95; }
.big-btn .bb-icon { width: 58px; height: 58px; border-radius: 18px; background: rgba(255,255,255,.25); display: grid; place-items: center; font-size: 30px; flex: none; }
.big-btn:active { transform: translateY(5px); }
.big-btn.play { background: linear-gradient(#45d28a, var(--green)); box-shadow: 0 7px 0 var(--green-d), 0 10px 18px rgba(0,0,0,.3); }
.big-btn.play:active { box-shadow: 0 2px 0 var(--green-d); }
.big-btn.daily { background: linear-gradient(#ffa865, var(--orange)); box-shadow: 0 7px 0 var(--orange-d), 0 10px 18px rgba(0,0,0,.3); }
.big-btn.daily:active { box-shadow: 0 2px 0 var(--orange-d); }
.big-btn.gold { background: linear-gradient(#ffd75e, var(--gold)); color: #5a3a00; text-shadow: none; box-shadow: 0 7px 0 var(--gold-d), 0 10px 18px rgba(0,0,0,.3); justify-content: center; text-align: center; }
.big-btn .streak { margin-left: auto; background: rgba(0,0,0,.18); border-radius: 999px; padding: 6px 12px; font-size: 20px; font-weight: 900; }
.big-btn.pulse { animation: pulse 1.6s ease-in-out infinite; }

.mid-btn { flex: 1; background: var(--cream); border-radius: 22px; padding: 14px 10px; font-size: 22px; font-weight: 900; display: flex; flex-direction: column; align-items: center; gap: 2px; box-shadow: 0 6px 0 var(--cream2), 0 9px 14px rgba(0,0,0,.25); }
.mid-btn > span { font-size: 34px; }
.mid-btn b, .tool b { font-weight: inherit; }   /* translated labels (data-t) */
.mid-btn:active { transform: translateY(5px); box-shadow: 0 1px 0 var(--cream2); }
.mid-badge { position: absolute; top: -8px; right: -6px; background: var(--pink); color: #fff; font-style: normal; font-size: 14px; padding: 2px 8px; border-radius: 999px; box-shadow: 0 2px 0 var(--pink-d); }
.link-btn { display: block; margin: 16px auto 0; font-size: 20px; color: var(--muted); padding: 8px 16px; }
.reset-btn { display: block; margin: 14px auto 0; padding: 10px 16px; border-radius: 14px; font-size: 17px; color: #b3261e; background: #fbe3df; }

/* ========== 3 home ========== */
#home { padding: 14px 18px 18px; overflow-y: auto; -webkit-overflow-scrolling: touch; overscroll-behavior: contain; }
#home > * { flex-shrink: 0; }
.home-top { display: flex; justify-content: space-between; align-items: center; }
.logo { text-align: center; margin: 2vh 0 2vh; flex: 1 0 auto; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.logo h1 { margin: 10px 0 0; font-size: clamp(38px, 11vw, 56px); font-weight: 900; color: #fff; letter-spacing: -.5px; text-shadow: 0 4px 0 rgba(0,0,0,.25), 0 8px 20px rgba(0,0,0,.25); }
.greet { margin: 4px 0 0; color: #fff; font-size: 22px; opacity: .95; text-shadow: 0 2px 0 rgba(0,0,0,.2); }
.logo-tiles { display: flex; gap: 6px; height: 108px; align-items: flex-end; }
.lt { width: 66px; height: 86px; border-radius: 12px; background: linear-gradient(#fffef8, #f4ead2); box-shadow: 4px 5px 0 #d9caa0, 7px 9px 0 #1f7a5c, 8px 12px 14px rgba(0,0,0,.35); padding: 4px; animation: bob 3s ease-in-out infinite; }
.lt svg { width: 100%; height: 100%; display: block; }
.lt.t1 { transform: rotate(-9deg); }
.lt.t2 { margin-bottom: 18px; animation-delay: -1s; }
.lt.t3 { transform: rotate(9deg); animation-delay: -2s; }
.home-buttons { display: flex; flex-direction: column; gap: 18px; }
.row2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }   /* never wider than the screen */
.row2 .mid-btn { min-width: 0; }
.row2 .mid-btn b { min-width: 0; white-space: nowrap; }   /* a long word gets a smaller font instead (fitTexts) */
.row2 .mid-btn { position: relative; flex-direction: row; justify-content: center; gap: 8px; padding: 12px 8px; font-size: 19px; }
.row2 .mid-btn > span { font-size: 28px; }
.task-chip { font-size: 17px; padding: 6px 12px; letter-spacing: 1px; }
.task-chip.ready { background: linear-gradient(#ffd75e, var(--gold)); color: #5a3a00; animation: chipPulse 1.1s ease-in-out infinite; }
@keyframes chipPulse { 50% { transform: scale(1.12); box-shadow: 0 0 0 4px rgba(255,210,60,.5), 0 0 18px 6px rgba(255,200,0,.6); } }
/* the next goal under the menu (also on the win screen) */
.goal { margin-top: 16px; background: rgba(0,0,0,.25); color: #fff; border-radius: 18px; padding: 10px 14px; font-size: 17px; text-align: center; min-height: 20px; }
.goal:empty { display: none; }
.goal .bar { height: 10px; background: rgba(255,255,255,.25); border-radius: 9px; margin-top: 6px; overflow: hidden; }
.goal .bar i { display: block; height: 100%; background: linear-gradient(90deg, #ffe17a, var(--gold)); border-radius: 9px; }
.goal.sun { display: flex; gap: 10px; align-items: center; text-align: left; background: linear-gradient(135deg, #ffe066, #f7b733); color: #5a3a00; box-shadow: 0 4px 0 #c98a12, 0 8px 16px rgba(0,0,0,.25); }
.goal.sun .g-ico { font-size: 40px; animation: spin 8s linear infinite; }
.goal.sun > div { flex: 1; }
.goal.sun .bar { background: rgba(90,58,0,.18); }
.goal.sun .bar i { background: linear-gradient(90deg, #fff6c2, #fff); }

/* ========== 4 menu screens: levels, calendar, themes, prizes ========== */
.header { display: flex; align-items: center; gap: 12px; padding: 14px 16px; }
.header h2 { flex: 1; margin: 0; color: #fff; font-size: 30px; font-weight: 900; text-shadow: 0 3px 0 rgba(0,0,0,.25); }
.scroll { flex: 1; overflow-y: auto; padding: 4px 16px 28px; -webkit-overflow-scrolling: touch; }
.card { background: var(--cream); border-radius: 22px; padding: 16px; box-shadow: 0 6px 0 var(--cream2), 0 9px 16px rgba(0,0,0,.22); margin-bottom: 18px; }
h3.sec { color: #fff; font-size: 22px; margin: 6px 4px 10px; text-shadow: 0 2px 0 rgba(0,0,0,.25); }

/* levels */
.level-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px 10px; }
.lv { aspect-ratio: 1; border-radius: 22px; background: var(--cream); box-shadow: 0 6px 0 var(--cream2), 0 8px 12px rgba(0,0,0,.22); display: flex; flex-direction: column; align-items: center; justify-content: center; font-size: 28px; font-weight: 900; }
.lv small { font-size: 15px; letter-spacing: 1px; color: var(--gold-d); line-height: 1; margin-top: 2px; }
.lv small .off { color: #d8cdb0; }
.lv.current { background: linear-gradient(#45d28a, var(--green)); color: #fff; box-shadow: 0 6px 0 var(--green-d), 0 0 0 4px #fff, 0 8px 16px rgba(0,0,0,.3); animation: pulse 1.6s ease-in-out infinite; }
.lv.locked { background: rgba(20,30,25,.3); color: rgba(255,255,255,.7); box-shadow: none; font-size: 22px; }
.lv:active:not(.locked) { transform: translateY(4px); }
.lv.prize { position: relative; box-shadow: 0 6px 0 #c98a12, 0 0 0 4px #ffd23f, 0 8px 18px rgba(255,190,0,.6); }
.lv .prize-ico { position: absolute; top: -12px; right: -8px; font-size: 30px; animation: spin 8s linear infinite; }

/* daily puzzle calendar */
.streak-card { display: flex; align-items: center; gap: 14px; }
.streak-card .flame { font-size: 48px; animation: bob 2s ease-in-out infinite; }
.streak-card b { font-size: 24px; display: block; }
.streak-card small { font-size: 17px; color: var(--muted); }
.cal-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.cal-head b { font-size: 22px; text-transform: capitalize; }
.cal-days, .cal-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 6px; text-align: center; }
.cal-days span { font-size: 15px; color: #9b8758; }
.cal-grid { margin-top: 6px; }
.cd { aspect-ratio: 1; border-radius: 50%; display: grid; place-items: center; font-size: 19px; font-weight: 900; position: relative; }
.cd.future { color: #d6cbb0; }
.cd.done { background: radial-gradient(circle at 35% 30%, #ffe680, var(--gold) 60%, var(--gold-d)); color: #6a4500; box-shadow: 0 3px 0 #b07c00; }
.cd.done::after { content: '👑'; position: absolute; top: -9px; right: -5px; font-size: 14px; }
.cd.sel { outline: 4px solid var(--orange); outline-offset: 1px; }
.cd.today:not(.done) { background: #ffe9d6; }
.cal-count { text-align: center; margin-top: 12px; font-size: 18px; color: var(--muted); }

/* themes */
.theme-list { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 20px; }
.th { background: var(--cream); border-radius: 20px; padding: 12px 10px; box-shadow: 0 6px 0 var(--cream2), 0 8px 12px rgba(0,0,0,.2); text-align: center; font-size: 20px; font-weight: 900; position: relative; }
.th .pv { display: flex; justify-content: center; gap: 5px; margin-bottom: 8px; }
.th .pv .mini { width: 40px; height: 52px; border-radius: 8px; background: linear-gradient(#fffef8, #f1e6cb); box-shadow: 2px 3px 0 #d9caa0, 3px 5px 0 #1f7a5c; display: grid; place-items: center; padding: 2px; }
.th .pv .mini svg { width: 100%; height: 100%; }
.th .pv .mini .emo { font-size: 28px; }
.th.on, .bgc.on { box-shadow: 0 6px 0 var(--green-d), 0 0 0 5px var(--green), 0 8px 14px rgba(0,0,0,.25); }
.th.on::after, .bgc.on::after, .suncard.on::after { content: '✓'; position: absolute; top: -10px; right: -8px; width: 34px; height: 34px; border-radius: 50%; background: var(--green); color: #fff; display: grid; place-items: center; font-size: 22px; box-shadow: 0 2px 0 var(--green-d); }
.bg-list { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.bgc { position: relative; height: 110px; border-radius: 20px; box-shadow: 0 6px 0 rgba(0,0,0,.2), 0 8px 12px rgba(0,0,0,.2); display: flex; align-items: flex-end; padding: 10px; color: #fff; font-size: 19px; text-shadow: 0 2px 3px rgba(0,0,0,.5); }
.bgc.locked { filter: grayscale(.85) brightness(.75); }
.bgc .lock { position: absolute; inset: 0; display: grid; place-items: center; font-size: 22px; text-align: center; line-height: 1.2; }
/* the Zonnebloem prize card */
.suncard { position: relative; width: 100%; display: grid; grid-template-columns: auto 1fr; gap: 6px 12px; align-items: center; text-align: left; padding: 14px; margin-bottom: 18px; border-radius: 22px;
  background: linear-gradient(135deg, #fff3a6 0%, #ffd23f 55%, #f2a516 100%); color: #5a3a00; box-shadow: 0 6px 0 #c98a12, 0 10px 18px rgba(0,0,0,.25); }
.suncard .sun-ico { font-size: 58px; grid-row: span 2; animation: spin 10s linear infinite; }
.suncard .sun-txt b { display: block; font-size: 26px; font-weight: 900; }
.suncard .sun-txt small { display: block; font-size: 16px; }
.suncard .bar { display: block; height: 10px; border-radius: 9px; background: rgba(90,58,0,.18); margin: 6px 0 2px; overflow: hidden; }
.suncard .bar i { display: block; height: 100%; background: #fff; border-radius: 9px; }
.suncard .sun-pv { grid-column: 2; display: flex; gap: 5px; }
.suncard .mini { width: 38px; height: 48px; border-radius: 8px; background: linear-gradient(#fffdf0, #fff0b8); box-shadow: 2px 3px 0 #e6c25a, 3px 5px 0 #5a9e3a; display: grid; place-items: center; }
.suncard .mini .emo { font-size: 26px; }
.suncard.locked { filter: saturate(.75); }
.suncard.locked .sun-pv { opacity: .55; }

/* prize cabinet */
.trophy-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }   /* equal columns: a long name gets a smaller font */
.trophy { min-width: 0; }
.trophy b, .trophy small { max-width: 100%; }
.trophy { background: rgba(20,30,25,.38); color: #fff; border-radius: 20px; padding: 12px 10px; text-align: center; display: flex; flex-direction: column; align-items: center; gap: 2px; }
.trophy .t-ico { font-size: 40px; filter: grayscale(1); opacity: .45; }
.trophy b { font-size: 17px; }
.trophy small { font-size: 14px; opacity: .9; line-height: 1.2; }
.trophy em { font-style: normal; font-size: 14px; opacity: .9; }
.trophy .bar { width: 80%; height: 8px; border-radius: 6px; background: rgba(0,0,0,.25); overflow: hidden; margin-top: 4px; }
.trophy .bar i { display: block; height: 100%; background: var(--gold); }
.trophy.got { background: var(--cream); color: var(--ink); box-shadow: 0 5px 0 var(--cream2), 0 8px 14px rgba(0,0,0,.22); }
.trophy.got .t-ico { filter: none; opacity: 1; animation: bob 3s ease-in-out infinite; }
.trophy.got em { color: var(--green-d); font-weight: 900; }

/* ========== 5 game screen ========== */
.topbar { display: flex; align-items: center; gap: 10px; padding: 10px 12px 6px; }
#game .topbar { padding: 6px 10px 4px; gap: 8px; }
#game .icon-btn { width: 44px; height: 44px; font-size: 22px; border-radius: 14px; box-shadow: 0 4px 0 var(--cream2), 0 6px 8px rgba(0,0,0,.22); }
#btnRestart, #game #btnRestart { font-size: 26px; font-weight: 900; }
.title-wrap { position: relative; flex: 1; color: #fff; text-align: center; }
#gameTitle { font-size: 19px; font-weight: 900; text-shadow: 0 2px 0 rgba(0,0,0,.25); }
.progress { height: 12px; border-radius: 9px; background: rgba(0,0,0,.28); margin-top: 4px; overflow: hidden; }
#progressBar.shine { animation: barShine 1s ease; }
@keyframes barShine { 30% { filter: brightness(1.5) saturate(1.3); box-shadow: 0 0 14px 4px rgba(255,220,80,.9); } }
#progressBar { height: 100%; width: 0; border-radius: 9px; background: linear-gradient(90deg, #ffe17a, var(--gold)); transition: width .4s cubic-bezier(.3,1.4,.6,1); box-shadow: inset 0 -2px 0 rgba(0,0,0,.12); }
.chip.score { min-width: 60px; text-align: center; font-size: 17px; padding: 4px 10px; }
.chip.score.bump { animation: bump .35s ease; }
@keyframes bump { 40% { transform: scale(1.25); background: var(--gold); color: #5a3a00; } }
/* the combo sign sits over the level name, never over the tiles */
#comboTag { position: absolute; top: -3px; left: 50%; z-index: 5; pointer-events: none; white-space: nowrap; background: var(--pink); color: #fff; border-radius: 999px; padding: 1px 8px; font-size: 11px; font-weight: 900; box-shadow: 0 2px 0 var(--pink-d); opacity: 0; transform: translateX(-50%) scale(.6); transition: all .2s; }
#comboTag.on { opacity: 1; transform: translateX(-50%) scale(1); }

/* every finger goes straight to the game; the praise text stays above the tiles */
#boardWrap { flex: 1; position: relative; overflow: hidden; isolation: isolate; touch-action: none; -webkit-touch-callout: none; }
#board { position: absolute; inset: 0; --d: 5px; --fs: 30px; }

/* the message strip: praise and tips while playing, between the tray and the pile */
/* messages while playing: in the title spot of the top bar (title and progress step aside), never over the tiles */
#gameMsg { position: absolute; inset: -4px -2px; display: flex; align-items: center; justify-content: center; pointer-events: none; text-align: center; overflow: hidden; z-index: 4; }
.title-wrap > #gameTitle, .title-wrap > .progress { transition: opacity .25s; }
.title-wrap.msg-on > #gameTitle, .title-wrap.msg-on > .progress { opacity: 0; }
#gameMsg span { max-width: 100%; animation: msgIn .35s cubic-bezier(.3,1.6,.5,1); transition: opacity .35s, transform .35s; }
#gameMsg span.out { opacity: 0; transform: translateY(-8px); }
#gameMsg .msg { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; background: rgba(25,18,5,.62); color: #fff; font-size: 14.5px; font-weight: 800; line-height: 1.15; padding: 3px 10px; border-radius: 12px; }
#gameMsg .big { font-size: 23px; font-weight: 900; color: #fff; line-height: 1; white-space: nowrap; -webkit-text-stroke: 1px rgba(120,60,0,.35); text-shadow: 0 3px 0 #e08a00, 0 6px 14px rgba(0,0,0,.35); }
@keyframes msgIn { from { opacity: 0; transform: scale(.4); } to { opacity: 1; transform: scale(1); } }
.float { position: fixed; z-index: 60; pointer-events: none; color: #fff; font-weight: 900; font-size: 26px; text-shadow: 0 2px 0 #c77700, 0 4px 8px rgba(0,0,0,.4); animation: floatUp .9s ease-out forwards; }
.float.sc { font-size: 22px; animation: floatSc .9s ease-out forwards; }
@keyframes floatSc { from { transform: translate(-50%, 18px) scale(1.4); opacity: 0; } 25% { opacity: 1; transform: translate(-50%, 6px) scale(1.15); } to { transform: translate(-50%, -14px) scale(.7); opacity: 0; } }
@keyframes floatUp { from { transform: translate(-50%, 0) scale(.7); opacity: 1; } 30% { transform: translate(-50%, -20px) scale(1.2); } to { transform: translate(-50%, -70px) scale(1); opacity: 0; } }
#fx { position: fixed; inset: 0; width: 100%; height: 100%; pointer-events: none; z-index: 70; }
#toast { position: fixed; left: 50%; bottom: calc(120px + var(--safe-bot)); transform: translate(-50%, 30px); background: rgba(30,20,5,.88); color: #fff; padding: 12px 20px; border-radius: 18px; font-size: 19px; opacity: 0; transition: all .3s; z-index: 80; width: max-content; max-width: min(88vw, 420px); text-align: center; pointer-events: none; }
#toast.on { opacity: 1; transform: translate(-50%, 0); }
#toast.top { bottom: auto; top: calc(10px + var(--safe-top)); transform: translate(-50%, -30px); }
#toast.top.on { transform: translate(-50%, 0); }

/* a stuck tile: arrows to the tiles in the way */
.blk-arrow { position: absolute; z-index: 2000000; pointer-events: none; transform: translate(-50%, -50%) rotate(var(--a)); animation: blkNudge 1.3s ease-in-out forwards; filter: drop-shadow(0 2px 3px rgba(0,0,0,.45)); }
.blk-arrow svg { width: 100%; height: 100%; display: block; }
@keyframes blkNudge {
  0% { opacity: 0; transform: translate(-50%, -50%) rotate(var(--a)) translateX(-40%) scale(.6); }
  15% { opacity: 1; transform: translate(-50%, -50%) rotate(var(--a)) translateX(0) scale(1); }
  30% { transform: translate(-50%, -50%) rotate(var(--a)) translateX(22%); }
  45% { transform: translate(-50%, -50%) rotate(var(--a)) translateX(0); }
  60% { transform: translate(-50%, -50%) rotate(var(--a)) translateX(22%); }
  80% { opacity: 1; transform: translate(-50%, -50%) rotate(var(--a)) translateX(0); }
  100% { opacity: 0; transform: translate(-50%, -50%) rotate(var(--a)) translateX(0); }
}

/* ========== 6 tiles ========== */
.tile { position: absolute; border-radius: 14%; background: linear-gradient(160deg, #fffef9 0%, #fbf4e2 55%, #efe2c0 100%);
  box-shadow: calc(var(--d) * .5) calc(var(--d) * .6) 0 0 #e1d2a8, var(--d) calc(var(--d) * 1.2) 0 0 #27906d, calc(var(--d) * 1.1) calc(var(--d) * 1.5) calc(var(--d) * 1.2) 0 rgba(0,0,0,.35);
  transition: transform .14s ease, opacity .25s ease; cursor: pointer; }
.tile .face { position: absolute; inset: 5% 6%; display: grid; place-items: center; pointer-events: none; }
.tile .face svg { width: 100%; height: 100%; display: block; }
.tile .emo { font-size: var(--fs); line-height: 1; font-family: 'Noto Color Emoji', 'Apple Color Emoji', 'Segoe UI Emoji', sans-serif; }
.tile::after { content: ''; position: absolute; inset: 0; border-radius: inherit; background: rgba(60,40,10,.30); opacity: 0; transition: opacity .25s; pointer-events: none; }
#board.hl .tile.blocked::after { opacity: 1; }
.tile.hint::before { content: ''; position: absolute; inset: -4px; border-radius: 16%; border: 4px solid #4fc3ff; box-shadow: 0 0 18px 6px rgba(80,200,255,.8); animation: hintGlow .7s ease-in-out infinite alternate; pointer-events: none; }
@keyframes hintGlow { to { box-shadow: 0 0 6px 2px rgba(80,200,255,.5); } }
.tile.shake { animation: shake .3s; }
@keyframes shake { 20%, 60% { translate: -5px 0; } 40%, 80% { translate: 5px 0; } }
.tile.hidden { display: none; }
.tile.returning { visibility: hidden; }   /* put back from the tray: shown when its flying copy lands */
.tile.flip { animation: flip .45s ease; }
@keyframes flip { 0% { transform: scale(1); } 45% { transform: scale(.2) rotate(15deg); opacity: .4; } 100% { transform: scale(1); } }
.tile.enter { animation: enter .5s backwards cubic-bezier(.3,1.5,.6,1); }
@keyframes enter { from { transform: translateY(-40px) scale(.4); opacity: 0; } }
.tile.flying { position: fixed; z-index: 90; transform-origin: 0 0; pointer-events: none; margin: 0; }
.popout { animation: popout .23s ease forwards !important; }
@keyframes popout { to { transform: scale(1.35); opacity: 0; } }
.tile.flying.popout { animation: none !important; opacity: 0; transition: opacity .2s !important; }
#board .tile.blocker { animation: blockerPulse 1.3s ease-in-out; }
#board .tile.blocker::after { opacity: 0 !important; }
@keyframes blockerPulse {
  0%, 100% { box-shadow: calc(var(--d) * .5) calc(var(--d) * .6) 0 0 #e1d2a8, var(--d) calc(var(--d) * 1.2) 0 0 #27906d; }
  25%, 65% { box-shadow: 0 0 0 4px #ff8a00, 0 0 16px 5px rgba(255,140,0,.75); }
  45% { box-shadow: 0 0 0 2px #ff8a00, 0 0 6px 2px rgba(255,140,0,.5); }
}
/* face-down tiles */
.tile.back { background:
    radial-gradient(circle at 50% 50%, #ffe08a 0 9%, #e8b13a 10% 14%, transparent 15%),
    repeating-linear-gradient(45deg, rgba(255,255,255,.13) 0 2px, transparent 2px 8px),
    repeating-linear-gradient(-45deg, rgba(255,255,255,.13) 0 2px, transparent 2px 8px),
    linear-gradient(160deg, #3dbb90, #1b8063); }
.tile.back .face { visibility: hidden; }
.tile.back::after { background: rgba(10,30,20,.35); }
/* corner numbers can be switched off in the settings */
body.nonum .cn { display: none; }

/* ========== 7 tray & tools ========== */
.traybar { display: flex; justify-content: center; padding: 0 12px 4px; }
#tray { --slotw: min(12.5vw, 60px, 7vh); display: grid; grid-template-columns: repeat(4, var(--slotw)); gap: 6px; padding: 6px; border-radius: 16px;
  background: linear-gradient(#8a5a33, #6b4224); box-shadow: inset 0 3px 6px rgba(0,0,0,.45), 0 4px 0 #4a2d17, 0 8px 14px rgba(0,0,0,.3); transition: box-shadow .3s; --sfs: 30px; }
#tray .slot { aspect-ratio: 1 / 1.24; border-radius: 10px; background: rgba(0,0,0,.28); box-shadow: inset 0 3px 5px rgba(0,0,0,.45); position: relative; }
#tray.warn { box-shadow: inset 0 3px 6px rgba(0,0,0,.45), 0 4px 0 #4a2d17, 0 0 0 4px #ffb300, 0 8px 18px rgba(255,170,0,.55); }
#tray.full { box-shadow: inset 0 3px 6px rgba(0,0,0,.45), 0 4px 0 #4a2d17, 0 0 0 4px #ff4d4d, 0 8px 22px rgba(255,60,60,.6); animation: trayPulse 1s ease-in-out infinite; }
@keyframes trayPulse { 50% { transform: scale(1.02); } }
.tmini { position: absolute; inset: 0; border-radius: 10px; background: linear-gradient(160deg, #fffef9, #efe2c0); box-shadow: 2px 2px 0 #d9caa0, 2px 4px 0 #27906d; display: grid; place-items: center; padding: 3px; }
.tmini svg { width: 100%; height: 100%; display: block; }
.tmini .emo { font-size: var(--sfs); line-height: 1; }
.tmini.land { animation: land .25s ease; }
@keyframes land { 0% { transform: scale(1.15); } 100% { transform: scale(1); } }
.tmini.arriving { visibility: hidden; }
.tmini.ghost { position: fixed; inset: auto; z-index: 89; pointer-events: none; }

.toolbar { display: flex; justify-content: center; gap: 14px; padding: 4px 14px 10px; }
.tool { position: relative; flex: 0 1 140px; display: flex; flex-direction: row; align-items: center; justify-content: center; gap: 6px; padding: 6px 10px; background: var(--cream); border-radius: 16px; font-size: 16px; font-weight: 900; box-shadow: 0 4px 0 var(--cream2), 0 6px 10px rgba(0,0,0,.22); }
.tool > span { font-size: 22px; line-height: 1; }
.tool:active { transform: translateY(5px); box-shadow: 0 1px 0 var(--cream2); }
.tool .badge { position: absolute; top: -7px; right: -5px; min-width: 22px; height: 22px; border-radius: 13px; background: var(--pink); color: #fff; font-style: normal; font-size: 14px; display: grid; place-items: center; box-shadow: 0 2px 0 var(--pink-d); }
.tool.used { opacity: .45; filter: grayscale(1); }
.tool.locked { opacity: .55; filter: grayscale(.8); }
.tool.locked .badge { background: var(--muted); box-shadow: 0 2px 0 #5c4520; font-size: 12px; }

/* ========== 8 pop-ups ========== */
#modal { position: fixed; inset: 0; background: rgba(10,20,15,.6); display: grid; place-items: center; z-index: 65; padding: 20px; }
#modal.hidden { display: none; }
.modal-box { width: 100%; max-width: 420px; background: var(--cream); border-radius: 28px; padding: 24px 20px 20px; text-align: center; box-shadow: 0 8px 0 var(--cream2), 0 20px 40px rgba(0,0,0,.4); animation: pop .4s cubic-bezier(.3,1.5,.6,1); max-height: 92vh; overflow-y: auto; }
.modal-box h2 { margin: 0 0 6px; font-size: 32px; font-weight: 900; }
.modal-box p { font-size: 20px; margin: 8px 0 16px; line-height: 1.35; }
.modal-box .big-btn { justify-content: center; text-align: center; margin-top: 10px; }
.modal-box .big-btn b { font-size: 26px; }
.modal-box .note { font-size: 17px; color: var(--muted); }
.modal-box .note.small { font-size: 16px; }
/* settings */
.set-row { display: flex; justify-content: space-between; align-items: center; padding: 14px 4px; border-bottom: 2px dashed #eadcb6; font-size: 21px; text-align: left; }
.set-row:last-of-type { border-bottom: 0; }
/* language choice: two buttons side by side */
.lang-pick { display: flex; gap: 6px; }
.lang-pick .lp { font: inherit; font-size: 16px; font-weight: 800; padding: 7px 11px; border-radius: 12px; border: 2px solid #d9c38f; background: #fff8e6; color: var(--ink); cursor: pointer; }
.lang-pick .lp.on { background: var(--green, #2fa36b); border-color: transparent; color: #fff; }
.tog { width: 72px; height: 40px; border-radius: 999px; background: #d8ccb0; position: relative; transition: background .2s; flex: none; }
.tog::after { content: ''; position: absolute; top: 4px; left: 4px; width: 32px; height: 32px; border-radius: 50%; background: #fff; box-shadow: 0 2px 4px rgba(0,0,0,.3); transition: left .2s; }
.tog.on { background: var(--green); }
.tog.on::after { left: 36px; }
.version { margin-top: 10px; font-size: 14px; color: #9b8758; }
/* how to play: a little tray with tiles */
.how-tray { display: grid; grid-template-columns: repeat(4, 52px); gap: 6px; justify-content: center; padding: 8px; margin: 6px auto 10px; width: max-content; border-radius: 16px; background: linear-gradient(#8a5a33, #6b4224); }
.how-tray .hm { height: 66px; border-radius: 9px; background: linear-gradient(#fffef8, #f1e6cb); padding: 3px; }
.how-tray .hm svg { width: 100%; height: 100%; }
.how-tray .hm.empty { background: rgba(0,0,0,.28); }
.how-tray .hm.glow { outline: 4px solid #ffb300; outline-offset: 1px; }
.backmini { background:
    radial-gradient(circle at 50% 50%, #ffe08a 0 9%, #e8b13a 10% 14%, transparent 15%),
    repeating-linear-gradient(45deg, rgba(255,255,255,.13) 0 2px, transparent 2px 8px),
    linear-gradient(160deg, #3dbb90, #1b8063) !important; }
.unlock-pv { height: 120px; border-radius: 20px; margin: 10px 0; box-shadow: inset 0 0 0 4px rgba(255,255,255,.6); }
/* name and avatar */
.name-in { width: 100%; font: inherit; font-size: 22px; padding: 12px 14px; border-radius: 14px; border: 3px solid #e6d6ac; background: #fff; color: var(--ink); text-align: center; user-select: text; -webkit-user-select: text; }
.name-in:focus { outline: none; border-color: var(--gold); }
.quick-names { display: flex; gap: 8px; justify-content: center; align-items: center; margin: 10px 0; flex-wrap: nowrap; }   /* one row in every language (fitTexts: .fit-row) */
.qn { background: #efe2c0; border-radius: 999px; padding: .35em .8em; font-size: 1em; white-space: nowrap; flex: 0 1 auto; }
.quick-names { font-size: 17px; }
.avatars { display: grid; grid-template-columns: repeat(6, 1fr); gap: 6px; margin: 4px 0 6px; }
.av { font-size: 28px; border-radius: 12px; padding: 4px 0; background: #fff; }
.av.on { background: #ffe58a; box-shadow: 0 0 0 3px var(--gold); }
.fr-title { margin: 12px 0 6px; font-size: 19px; }
.frames { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-bottom: 8px; }
.frm { background: #fff; border-radius: 14px; padding: 10px 2px 6px; display: grid; justify-items: center; gap: 6px; }
.frm .ra { width: 44px; height: 44px; font-size: 26px; }
.frm small { font-size: 11px; line-height: 1.15; color: #6a5530; font-weight: 800; }
.frm.on { background: #ffe58a; box-shadow: 0 0 0 3px var(--gold); }
.frm.locked { opacity: .5; }
.frm.locked .ra { filter: grayscale(1); }

/* ========== 9 celebrations ========== */
.stars { display: flex; justify-content: center; gap: 6px; margin: 10px 0 8px; height: 84px; align-items: flex-end; }
.stars .st { font-size: 64px; color: #e2d6b5; line-height: 1; transform: scale(.5); opacity: .5; transition: all .4s cubic-bezier(.3,1.8,.5,1); }
.stars .st:nth-child(2) { font-size: 80px; }
.stars .st.on { color: var(--gold); transform: scale(1); opacity: 1; text-shadow: 0 4px 0 var(--gold-d), 0 0 22px rgba(255,200,0,.8); }
.win-stats { display: flex; justify-content: center; gap: 12px; margin: 8px 0 6px; }
.win-stats div { background: #fff; border-radius: 16px; padding: 8px 14px; font-size: 16px; color: var(--muted); min-width: 96px; }
.win-stats b { display: block; font-size: 26px; color: var(--ink); }
.perfect { height: 0; overflow: visible; font-size: 30px; font-weight: 900; color: #ff8a00; text-shadow: 0 3px 0 #ffd23f; opacity: 0; transform: scale(.3) rotate(-10deg); transition: all .45s cubic-bezier(.3,1.8,.5,1); }
.perfect.on { height: 40px; opacity: 1; transform: scale(1) rotate(-4deg); }
.chase { font-size: 17px !important; margin: 6px 0 4px !important; color: #5c4520; }
.sun-big { font-size: 96px; line-height: 1; animation: sunPop 1.2s cubic-bezier(.3,1.6,.5,1), spin 9s linear 1.2s infinite; }
@keyframes sunPop { 0% { transform: scale(.1) rotate(-180deg); } 100% { transform: scale(1) rotate(0); } }
.tools-new { display: flex; justify-content: center; gap: 18px; font-size: 64px; margin: 6px 0; }
.tools-new span { animation: sunPop 1s cubic-bezier(.3,1.6,.5,1) backwards; }
.tools-new span:nth-child(2) { animation-delay: .2s; }
.tools-new.off span { filter: grayscale(1); opacity: .45; }   /* not earned (from level 50) */
.tr-new { display: grid; gap: 10px; margin: 12px 0; }
.trn { display: flex; align-items: center; gap: 12px; background: #fff; border-radius: 16px; padding: 10px 12px; text-align: left; animation: pop .5s cubic-bezier(.3,1.5,.6,1) backwards; }
.trn:nth-child(2) { animation-delay: .15s; } .trn:nth-child(3) { animation-delay: .3s; } .trn:nth-child(4) { animation-delay: .45s; }
.trn span { font-size: 40px; }
.trn b { display: block; font-size: 20px; }
.trn small { font-size: 15px; color: var(--muted); }
#flash { position: fixed; inset: 0; pointer-events: none; z-index: 75; opacity: 0;
  background: radial-gradient(circle at 50% 45%, rgba(255,255,255,.85) 0%, rgba(255,230,120,.5) 25%, rgba(255,120,200,.3) 45%, rgba(120,200,255,.2) 65%, transparent 80%); }
#flash.on { animation: flash .7s ease-out; }
@keyframes flash { 0% { opacity: 0; } 15% { opacity: 1; } 100% { opacity: 0; } }
.bee { position: fixed; left: -60px; z-index: 76; font-size: 40px; pointer-events: none; animation: beefly 2.6s ease-in-out forwards; }
@keyframes beefly {
  0% { transform: translate(0, 0) scaleX(-1); }
  25% { transform: translate(30vw, -40px) scaleX(-1); }
  50% { transform: translate(55vw, 30px) scaleX(-1); }
  75% { transform: translate(80vw, -30px) scaleX(-1); }
  100% { transform: translate(115vw, 10px) scaleX(-1); }
}
/* hearts */
.heart-big { font-size: 110px; line-height: 1; margin: 0 0 4px; animation: heartBeat 1s ease-in-out infinite; filter: drop-shadow(0 6px 10px rgba(232,87,140,.45)); }
@keyframes heartBeat { 0%, 100% { transform: scale(1); } 15% { transform: scale(1.18); } 30% { transform: scale(1); } 45% { transform: scale(1.12); } }
.heart-h { color: #c2306b; }
.heart-who { font-size: 23px !important; }
#heartPop { position: fixed; inset: 0; z-index: 64; display: none; place-items: center; background: rgba(60,10,30,.35); }
#heartPop.on { display: grid; animation: fadeIn .25s ease; }
#heartPop .hp-card { background: var(--cream); color: var(--ink); border-radius: 26px; padding: 16px 26px 14px; text-align: center; display: grid; gap: 2px; border: 4px solid #ff7aa8; box-shadow: 0 8px 0 #e85d8f, 0 18px 40px rgba(0,0,0,.4); animation: pop .45s cubic-bezier(.3,1.6,.5,1); max-width: 86vw; }
#heartPop .hp-heart { font-size: 96px; line-height: 1; animation: heartBeat 1s ease-in-out infinite; }
#heartPop b { font-size: 26px; color: #c2306b; }
#heartPop span { font-size: 21px; font-weight: 800; }
#heartPop small { font-size: 15px; color: var(--muted); margin-top: 6px; }

/* ========== 10 leaderboard & family ========== */
.name-chip { display: block; margin: 0 auto 14px; background: var(--cream); color: var(--ink); border-radius: 999px; padding: 8px 18px; font-size: 19px; font-weight: 900; box-shadow: 0 4px 0 var(--cream2), 0 6px 10px rgba(0,0,0,.2); }
.rk-tabs { display: flex; gap: 8px; justify-content: center; margin: 0 0 8px; }
.rk-tabs button { flex: 1; max-width: 180px; background: rgba(0,0,0,.25); color: #fff; border-radius: 999px; padding: 8px 10px; font-size: 17px; font-weight: 900; }
.rk-tabs button.on { background: var(--cream); color: var(--ink); box-shadow: 0 3px 0 var(--cream2); }
.wk-info { text-align: center; color: #fff; font-size: 15px; font-weight: 700; margin: 0 0 10px; text-shadow: 0 1px 2px rgba(0,0,0,.4); line-height: 1.35; }
.wk-info b { color: #ffe27a; }
.rank-list { display: grid; gap: 8px; }
.rrow { display: grid; grid-template-columns: 46px 40px 1fr auto; align-items: center; gap: 6px; background: var(--cream); color: var(--ink); border-radius: 16px; padding: 6px 12px; height: 52px; box-shadow: 0 3px 0 var(--cream2); }
.rrow .rk { font-size: 20px; font-weight: 900; text-align: center; color: var(--muted); }
.rrow .rn { font-size: 18px; font-weight: 900; line-height: 1.1; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.rrow .rn i { font-style: normal; font-weight: 700; font-size: 14px; color: var(--muted); }
.rrow .rn small { display: block; font-size: 13px; color: #9b8758; font-weight: 700; }
.rrow .rp { font-size: 19px; font-weight: 900; font-variant-numeric: tabular-nums; }
.rrow.me { background: linear-gradient(135deg, #fff3a6, #ffd23f); box-shadow: 0 3px 0 #d99a00, 0 0 0 3px #ffb300; }
.rrow.fam { background: linear-gradient(135deg, #ffe9f1, #ffcfe1); box-shadow: 0 3px 0 #e85d8f, 0 0 0 3px #ff7aa8; }
.rrow .fam-tag { font-style: normal; font-size: 16px; font-weight: 900; vertical-align: 0; }
.rank-note { text-align: center; color: #fff; font-size: 15px; opacity: .9; margin-top: 14px; text-shadow: 0 1px 2px rgba(0,0,0,.4); }
.heart-btn { margin-left: 6px; font-size: 18px; background: #fff3c4; border-radius: 999px; padding: 2px 7px; vertical-align: middle; box-shadow: 0 2px 0 #e6c96a; }
.heart-btn.sent { background: #e9f7df; box-shadow: none; font-size: 14px; opacity: .8; }
/* avatars and the frames you can earn */
.ra { display: inline-grid; place-items: center; border-radius: 50%; }
.rrow .ra { width: 38px; height: 38px; font-size: 24px; text-align: center; justify-self: center; }
.ra.small { width: 28px; height: 28px; font-size: 18px; vertical-align: middle; }
.ra.fr-bronze { box-shadow: 0 0 0 3px #c47a3a, inset 0 0 0 2px #f0b27a; background: #fbe7d3; }
.ra.fr-silver { box-shadow: 0 0 0 3px #a9b4c0, inset 0 0 0 2px #eef2f6; background: #f1f4f8; }
.ra.fr-gold { box-shadow: 0 0 0 3px #e0a800, 0 0 8px 2px rgba(255,200,0,.6), inset 0 0 0 2px #ffe680; background: #fff6cc; }
.ra.fr-sun { box-shadow: 0 0 0 3px #ffb300, 0 0 0 6px #6aa83a; background: #fff2a8; }
.ra.fr-heart { box-shadow: 0 0 0 3px #ff6f91, 0 0 8px 2px rgba(255,110,150,.5); background: #ffe3ea; }
.ra.fr-rainbow { background: #fff; box-shadow: 0 0 0 1.5px #ff5252, 0 0 0 3px #ffb300, 0 0 0 4.5px #4caf50, 0 0 0 6px #2196f3; }
.ra.fr-crown { background: #fff6cc; box-shadow: 0 0 0 3px #e0a800, 0 0 12px 3px rgba(255,200,0,.7); position: relative; }
.ra.fr-crown::before { content: '👑'; position: absolute; top: -.62em; font-size: .55em; }
/* the family box (leaderboard, win screen, climb) */
.fam-box { background: linear-gradient(135deg, #ffe9f1, #ffd6e6); border: 3px solid #ff7aa8; border-radius: 18px; padding: 8px 10px 6px; margin: 8px 0 12px; box-shadow: 0 4px 0 #e85d8f; color: var(--ink); text-align: left; }
.fam-fixed { padding: 0 16px; }
.fam-fixed .fam-box { margin: 2px 0 8px; }
.modal-box .fam-box { margin: 10px 0 6px; }
.fam-title { font-size: 17px; font-weight: 900; color: #b8336a; margin: 0 0 4px 4px; }
.fam-row { display: grid; grid-template-columns: 44px 36px 1fr auto; align-items: center; gap: 6px; padding: 5px 4px; border-radius: 12px; }
.fam-row + .fam-row { border-top: 2px dashed rgba(184,51,106,.25); }
.fam-row.me { background: rgba(255,255,255,.65); }
.fam-row .fr-rank { font-size: 20px; font-weight: 900; text-align: center; color: #8a3a5c; }
.fam-row .ra { width: 34px; height: 34px; font-size: 22px; }
.fam-row .fr-name { font-size: 18px; font-weight: 900; line-height: 1.15; overflow: hidden; text-overflow: ellipsis; }
.modal-box .fam-row .fr-name { font-size: 16px; }
.fam-row .fr-name i { font-style: normal; font-size: 13px; color: var(--muted); }
.fam-row .fr-sub { display: block; font-size: 13.5px; font-weight: 800; color: #8a5a6e; }
.fam-row .fr-val { font-size: 17px; font-weight: 900; white-space: nowrap; font-variant-numeric: tabular-nums; }
.fam-row .hs { display: block; font-size: 12.5px; font-weight: 800; color: #b8336a; }
.fam-row .hs.seen { color: #2f8f3a; }
/* climbing past other players after a level */
.climb { position: relative; margin: 10px 0 6px; }
.climb .crow { position: absolute; left: 0; right: 0; transition: transform .45s cubic-bezier(.3,1.3,.5,1); }
.climb .crow.me { z-index: 2; }
.climb .crow.me.glow { animation: meGlow 1s ease-in-out 3; }
@keyframes meGlow { 50% { box-shadow: 0 3px 0 #d99a00, 0 0 0 4px #ffb300, 0 0 26px 8px rgba(255,200,0,.8); } }
.climb-msg { font-size: 19px; line-height: 1.35; min-height: 74px; }
.climb-msg small { font-size: 16px; color: var(--muted); }
.climb-up { display: inline-block; font-size: 30px; font-weight: 900; color: var(--green-d); animation: pop .5s cubic-bezier(.3,1.6,.5,1); }

/* the after-level screens (win + climb) are compact: everything fits without scrolling */
.modal-box.compact { padding: 16px 16px 12px; }
.compact h2 { font-size: 27px; line-height: 1.15; margin-bottom: 2px; }
.compact p { font-size: 16px; margin: 4px 0 6px; }
.compact .stars { height: 58px; margin: 2px 0 4px; }
.compact .stars .st { font-size: 46px; }
.compact .stars .st:nth-child(2) { font-size: 58px; }
.compact .win-stats { gap: 8px; margin: 4px 0; }
.compact .win-stats div { display: flex; align-items: baseline; gap: 6px; min-width: 0; padding: 4px 14px; font-size: 15px; }
.compact .win-stats b { display: inline; font-size: 22px; }
.compact .perfect { font-size: 24px; }
.win-stats .ws-streak { color: #c2410c; }
