.task .t-ico { font-size: 30px; text-align: center; }
.task b { display: block; font-size: 18px; line-height: 1.2; }
.task small { font-size: 14px; color: var(--muted); font-weight: 700; }
.task .bar { display: block; height: 12px; background: #efe2c0; border-radius: 8px; margin: 6px 0 3px; overflow: hidden; }
.task .bar i { display: block; height: 100%; background: linear-gradient(90deg, #8be06a, #3fae2a); border-radius: 8px; transition: width .4s; }
.task.done { background: #e8f8dc; }
.chest-btn { display: flex; align-items: center; gap: 12px; width: 100%; text-align: left; background: #efe2c0; color: #6a5530; border-radius: 18px; padding: 10px 14px; font-size: 17px; font-weight: 800; margin-bottom: 8px; }
.chest-btn .chest-ico { font-size: 40px; filter: grayscale(.7); }
.chest-btn.ready { background: linear-gradient(#ffe27a, var(--gold)); color: #5a3a00; box-shadow: 0 5px 0 var(--gold-d); animation: chipPulse 1.1s ease-in-out infinite; }
.chest-btn.ready .chest-ico { filter: none; animation: wiggle .6s ease-in-out infinite; }
.chest-btn.opened { opacity: .75; }
.chest-btn.opened .chest-ico { filter: none; }
@keyframes wiggle { 25% { transform: rotate(-12deg) scale(1.1); } 75% { transform: rotate(12deg) scale(1.1); } }
.chest-open { font-size: 90px; line-height: 1; margin: 4px 0; }
.chest-open .lid { display: inline-block; animation: chestPop 1s cubic-bezier(.3,1.6,.5,1); }
@keyframes chestPop { 0% { transform: scale(.2) rotate(-30deg); } 40% { transform: scale(1.3) rotate(10deg); } 100% { transform: scale(1); } }
.chest-loot { display: flex; justify-content: center; gap: 14px; margin: 10px 0; }
.chest-loot div { background: #fff; border-radius: 16px; padding: 8px 18px; display: grid; justify-items: center; font-size: 30px; box-shadow: 0 3px 0 var(--cream2); animation: pop .5s .3s cubic-bezier(.3,1.6,.5,1) backwards; }
.chest-loot div + div { animation-delay: .5s; }
