.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.stat { background: #fff; border-radius: 12px; padding: 6px 2px; display: grid; justify-items: center; text-align: center; }
.stat span { font-size: 22px; line-height: 1.1; }
.stat b { font-size: 18px; font-weight: 900; font-variant-numeric: tabular-nums; }
.stat small { font-size: 11.5px; color: var(--muted); font-weight: 700; line-height: 1.15; }

#board .tile.gold:not(.back) { background: linear-gradient(160deg, #fff8d0 0%, #ffe680 55%, #f2c230 100%); box-shadow: inset 0 0 0 2px #e0a800, 0 0 10px 2px rgba(255,200,0,.55); }
.tile.gold:not(.back) .face::after { content: '✨'; position: absolute; right: -6%; top: -8%; font-size: calc(var(--fs, 30px) * .32); line-height: 1; }
#board .tile.sp-joker:not(.back) { background: linear-gradient(160deg, #f3ecff 0%, #dccbff 60%, #c2a8ff 100%); }
.emo.sp { animation: spBob 1.6s ease-in-out infinite; display: inline-block; }
@keyframes spBob { 50% { transform: scale(1.1) rotate(-4deg); } }
/* a face-down tile that matches at once: it flips open while it flies */
.tile.flying.reveal .face { animation: faceReveal .26s ease-out; }
@keyframes faceReveal { from { transform: scaleX(0); } 60% { transform: scaleX(1.1); } }
/* ice, lock and key */
.tile .ob { position: absolute; inset: 0; border-radius: inherit; pointer-events: none; z-index: 2; }
.tile .ob::after { position: absolute; line-height: 1; font-size: calc(var(--fs, 30px) * .42); filter: drop-shadow(0 1px 1px rgba(0,0,0,.35)); }
.tile .ob[data-k^="ice"] { background: linear-gradient(155deg, rgba(225,245,255,.62) 0%, rgba(160,215,250,.5) 55%, rgba(120,190,240,.55) 100%); box-shadow: inset 0 0 0 3px rgba(140,205,255,.95), inset 0 0 14px 2px rgba(255,255,255,.9); }
.tile .ob[data-k="ice2"] { background: linear-gradient(155deg, rgba(225,245,255,.8) 0%, rgba(160,215,250,.72) 55%, rgba(110,180,235,.75) 100%); box-shadow: inset 0 0 0 5px rgba(120,195,255,1), inset 0 0 18px 4px rgba(255,255,255,.95); }
.tile .ob[data-k="ice"]::after { content: '❄️'; right: 2%; bottom: 3%; font-size: calc(var(--fs, 30px) * .5); }
.tile .ob[data-k="ice2"]::after { content: '❄️❄️'; right: 2%; bottom: 3%; font-size: calc(var(--fs, 30px) * .32); }
.tile .ob[data-k="lock"] { background: rgba(70,45,10,.26); box-shadow: inset 0 0 0 4px #9a6b1f; }
.tile .ob[data-k="lock"]::after { content: '🔒'; right: -4%; bottom: -3%; font-size: calc(var(--fs, 30px) * .62); filter: drop-shadow(0 2px 3px rgba(0,0,0,.5)); }
.tile .ob[data-k="key"] { box-shadow: inset 0 0 0 3px #e0a800, 0 0 10px 2px rgba(255,200,0,.6); }
.tile .ob[data-k="key"]::after { content: '🔑'; left: -4%; top: -6%; font-size: calc(var(--fs, 30px) * .46); }
/* the alarm clock: a badge with the moves left (red and pulsing for the last 5) */
#board .tile.clocked { box-shadow: 0 0 0 3px #ff7a2f, 0 0 12px 3px rgba(255,122,47,.6); }
#clockBadge { position: absolute; z-index: 1999999; display: flex; align-items: center; gap: 1px; padding: 1px 6px 1px 3px; border-radius: 99px; background: #fff3e6; border: 2px solid #ff7a2f; box-shadow: 0 2px 5px rgba(0,0,0,.4); line-height: 1.15; pointer-events: none; }
#clockBadge b { color: #b23c00; font-weight: 900; font-variant-numeric: tabular-nums; min-width: 1.2em; text-align: center; }
#clockBadge.urgent { background: #ff4d3d; border-color: #b51d10; animation: ckPulse .8s ease-in-out infinite; }
#clockBadge.urgent b { color: #fff; }
@keyframes ckPulse { 50% { transform: scale(1.18); } }
.ob-crack { position: absolute; inset: 0; border-radius: inherit; pointer-events: none; z-index: 3; background: radial-gradient(circle, rgba(255,255,255,.95) 0%, rgba(180,225,255,.7) 40%, transparent 70%); animation: crack .55s ease-out forwards; }
@keyframes crack { from { opacity: 1; transform: scale(.6); } to { opacity: 0; transform: scale(1.5); } }
#board .tile.obhint { animation: nudgeShake 1.3s ease-in-out 1; box-shadow: 0 0 0 4px #7fd0ff, 0 0 16px 6px rgba(120,200,255,.85); }
.nt-ico { font-size: 72px; line-height: 1.1; animation: giftWiggle 1.4s ease-in-out infinite; display: inline-block; }
.clock-help { padding: 16px; }
.clock-help .nt-ico { font-size: 40px; }
.clock-help h2 { font-size: 26px; }
.clock-help p { font-size: 16px; line-height: 1.3; margin: 6px 0 10px; }
.clock-help .big-btn { padding: 11px 16px; margin-top: 8px; }
.clock-help .big-btn b { font-size: 24px; }
.clock-help .link-btn { margin-top: 2px; padding: 6px 16px; }
/* the daily gift */
.gift-box { font-size: 86px; line-height: 1.1; cursor: pointer; display: inline-block; animation: giftWiggle 1.2s ease-in-out infinite; }
.gift-box.open { animation: pop .5s cubic-bezier(.3,1.6,.5,1); font-size: 64px; text-shadow: 0 4px 0 var(--gold-d), 0 0 22px rgba(255,200,0,.8); }
@keyframes giftWiggle { 0%, 60%, 100% { transform: rotate(0) scale(1); } 70% { transform: rotate(-10deg) scale(1.08); } 80% { transform: rotate(9deg) scale(1.08); } 90% { transform: rotate(-5deg); } }
/* grandma's helper: a pair that glows until it is matched */
/* a glowing tile is always free (nothing on top), so it is lifted above the whole pile (tiles use z-index layer*10000+...) */
#board .tile.nudge { animation: nudgeShake 1.4s ease-in-out infinite; box-shadow: 0 0 0 4px #ffd23f, 0 0 18px 7px rgba(255,205,50,.85); z-index: 1000000 !important; }
@keyframes nudgeShake { 0%, 45%, 100% { transform: translate(0) rotate(0); } 5% { transform: translateX(-4px) rotate(-5deg); } 12% { transform: translateX(4px) rotate(5deg); } 19% { transform: translateX(-4px) rotate(-4deg); } 26% { transform: translateX(3px) rotate(3deg); } 33% { transform: translateX(-2px) rotate(-2deg); } 40% { transform: translateX(1px) rotate(1deg); } }
#tray .slot.nudge { animation: nudgeShake 1.4s ease-in-out infinite; box-shadow: 0 0 0 4px #ffd23f, 0 0 14px 5px rgba(255,205,50,.8); }
/* see-through: the tiles on top of a stuck tile, briefly */
#board .tile.xray { opacity: .22; }
#board .tile.lucky { animation: luckyGlow .55s ease-in-out infinite alternate; z-index: 1000001 !important; }
@keyframes luckyGlow { from { box-shadow: 0 0 0 3px #7ee36a, 0 0 10px 3px rgba(110,230,90,.6); } to { box-shadow: 0 0 0 5px #b7ff9e, 0 0 26px 10px rgba(140,255,110,.9); } }
.tile.lucky .face::before { content: '🍀'; position: absolute; left: -10%; top: -10%; font-size: calc(var(--fs, 30px) * .45); line-height: 1; }

/* ========== 12 themes: Zonnebloem prize and high contrast ========== */
body.sunny .tile { background: linear-gradient(160deg, #fffef4 0%, #fff6d0 55%, #f9e39a 100%);
  box-shadow: calc(var(--d) * .5) calc(var(--d) * .6) 0 0 #efd27a, var(--d) calc(var(--d) * 1.2) 0 0 #5c9e34, calc(var(--d) * 1.1) calc(var(--d) * 1.5) calc(var(--d) * 1.2) 0 rgba(60,40,0,.35); }
body.sunny .tile.back { background: url(data:image/png;base64,) center / cover no-repeat; }
body.sunny #tray { background: linear-gradient(#f3b73a, #c98317); box-shadow: inset 0 3px 6px rgba(80,40,0,.45), 0 4px 0 #8a5a10, 0 8px 14px rgba(0,0,0,.3); }
body.sunny #tray .slot { background: rgba(90,50,0,.28); }
body.sunny .tmini { background: linear-gradient(160deg, #fffef4, #f9e39a); box-shadow: 2px 2px 0 #efd27a, 2px 4px 0 #5c9e34; }
body.sunny #progressBar { background: linear-gradient(90deg, #fff27a, #ffb300); }
#bg.sunfield::before { content: '🌻 🌻 🌻 🌻 🌻 🌻 🌻 🌻 🌻 🌻'; position: absolute; left: -30px; right: -30px; bottom: -14px; font-size: 64px; letter-spacing: -14px; white-space: nowrap; overflow: hidden; opacity: .85; }
#bg.sunfield::after { background: radial-gradient(circle at 50% 35%, transparent 55%, rgba(120,70,0,.18) 100%); }

body.contrast #board .tile:not(.back):not(.gold):not(.sp-joker) { background: #fff; }
body.contrast .tile { outline: 2px solid #222; outline-offset: -2px; }
body.contrast .tile .face svg { filter: contrast(1.6) saturate(1.3); }
body.contrast .tile .emo { filter: saturate(1.4) contrast(1.2); }
body.contrast #board.hl .tile.blocked::after { background: rgba(0,0,0,.42); }
body.contrast .chip, body.contrast .rk-tabs button { background: rgba(0,0,0,.6); }
body.contrast .modal-box, body.contrast .task, body.contrast .stat { color: #000; }
body.contrast .tmini { border: 2px solid #222; background: #fff; }

/* ========== 13 screen sizes ========== */
@media (min-height: 760px) { .home-buttons { gap: 22px; } }
@media (max-height: 620px) { .logo-tiles { display: none; } .logo { margin: 6px 0; } }
/* short screens (Safari with its bars): compact home screen, which also scrolls */
@media (max-height: 740px) {
  #home { padding-top: 10px; padding-bottom: 12px; }
  .logo { margin: 16px 0 8px; }
  .logo-tiles { height: 74px; }
  .logo-tiles .lt { width: 54px; height: 70px; }
  .logo h1 { font-size: clamp(32px, 9.5vw, 44px); margin-top: 4px; }
  .home-buttons { gap: 12px; }
  .home-buttons .big-btn { padding-top: 12px; padding-bottom: 12px; }
  .row2 .mid-btn { padding: 10px 8px; }
  #nextUnlock { margin-top: 10px; }
}
@media (max-height: 600px) {
  .compact .goal { display: none; }
  .compact .stars { height: 48px; }
  .compact .stars .st { font-size: 38px; }
  .compact .stars .st:nth-child(2) { font-size: 48px; }
}

/* a message that came with a heart */
.heart-msg { font-size: 22px !important; font-weight: 800; line-height: 1.3; margin: 6px 0 10px !important; padding: 10px 14px; background: #fff3f7; border: 2px dashed #ff9fc0; border-radius: 16px; color: var(--ink); }
.heart-msg small { display: block; font-size: 15px; font-weight: 700; color: #c2306b; margin-top: 2px; }
#heartPop .heart-msg { margin: 8px 0 0 !important; }
.heart-big.sm { font-size: 60px; }
.msg-pick { display: grid; gap: 8px; margin: 6px 0 12px; }
.msg-pick .mp { font: inherit; font-size: 19px; font-weight: 800; padding: 12px 10px; border-radius: 16px; border: 3px solid #ff9fc0; background: #fff3f7; color: var(--ink); cursor: pointer; }
.msg-pick .mp:active { transform: scale(.97); }

/* ---------- news from Apeldoorn and the neighbourhood (village.js) ---------- */
.toolbar.gone { display: none; }
/* auto-finish: a big message over the pile, which plays itself now */
#autoBanner { position: absolute; left: 50%; top: 50%; z-index: 3000000; width: min(86%, 380px); transform: translate(-50%, -50%) scale(.85); opacity: 0; pointer-events: none;
  display: grid; justify-items: center; gap: 4px; text-align: center; padding: 18px 16px; border-radius: 24px; color: #fff;
  background: rgba(16, 70, 52, .86); box-shadow: 0 10px 30px rgba(0,0,0,.35), inset 0 0 0 3px rgba(255,215,90,.75); transition: opacity .35s, transform .35s cubic-bezier(.3,1.5,.6,1); }
#autoBanner.on { opacity: 1; transform: translate(-50%, -50%) scale(1); }
#autoBanner .ab-ico { font-size: 44px; line-height: 1; }
#autoBanner b { font-size: clamp(22px, 6.4vw, 30px); line-height: 1.15; text-wrap: balance; }
#autoBanner span:last-child { font-size: clamp(18px, 5vw, 23px); font-weight: 800; color: #ffe27a; }
@media (prefers-reduced-motion: reduce) { #autoBanner { transition: opacity .2s; transform: translate(-50%, -50%); } }
.paper-chip { font-size: 20px; padding: 5px 12px; position: relative; }
.paper-chip.hidden { display: none; }
.paper-chip.new::after { content: ''; position: absolute; top: 3px; right: 5px; width: 11px; height: 11px; border-radius: 50%; background: #ff5a5f; box-shadow: 0 0 0 2px #fff; }
.modal-box.vg { text-align: left; }
.vg-head { font-weight: 900; font-size: 17px; color: #8a5a00; background: #fff1c4; border-radius: 999px; padding: 6px 14px; display: inline-flex; align-items: center; gap: 8px; margin-bottom: 10px; }
.vg-who { font-size: 24px; line-height: 1; }
.vg-photo { margin: 0 -6px 12px; border-radius: 18px; overflow: hidden; background: #efe3c6; aspect-ratio: 4 / 3; max-height: min(240px, 27vh); width: calc(100% + 12px); }
.vg-photo img { width: 100%; height: 100%; object-fit: cover; display: block; }
.vg.paper .vg-photo { max-height: 180px; }
.vg-title { font-size: 21px; line-height: 1.25; margin: 4px 0 10px; }
.vg-title small { display: block; font-size: 15px; color: #8d8d8d; font-weight: 800; margin-top: 2px; }
.vg-text { font-size: 20px; line-height: 1.45; margin: 0 0 12px; }
.vg-cliff { font-size: 19px; line-height: 1.4; font-weight: 800; color: #b25d00; background: #fff6df; border-radius: 14px; padding: 10px 12px; margin: 0 0 14px; }
.vg-end { font-size: 17px; font-weight: 800; color: #8d8d8d; text-align: center; margin: 0 0 14px; }
.vg .big-btn { justify-content: center; text-align: center; }
/* the button stays in view at the bottom, also when the news is long */
.vg #vgOk, .vg #vgClose { position: sticky; bottom: 0; margin-top: 4px; box-shadow: 0 7px 0 var(--green-d), 0 10px 18px rgba(0,0,0,.3), 0 -16px 12px 8px var(--cream), 0 16px 0 14px var(--cream); }
.vg-answers { display: grid; gap: 12px; margin-top: 6px; }
.vg-a { background: linear-gradient(#fffdf6, #ffeec2); color: #5a3a00; text-shadow: none; box-shadow: 0 6px 0 #e3c46a, 0 8px 14px rgba(0,0,0,.15); }
.vg-a:disabled { opacity: .55; }
.vg-a.right { background: linear-gradient(#8ee07d, #48b33a); color: #fff; opacity: 1; box-shadow: 0 6px 0 #2f8a24; }
.vg-a.wrong { background: linear-gradient(#ffb0a8, #e3584b); color: #fff; opacity: 1; box-shadow: 0 6px 0 #b13a2f; }
.vg.paper .vg-item { border-top: 2px dashed #e8dcc0; padding-top: 12px; margin-top: 12px; }
.vg.paper .vg-item:first-of-type { border-top: 0; margin-top: 0; }
.vg.paper .vg-text { font-size: 18px; }
.vg.paper > h2 { text-align: center; }
.vg-chat { border: 0; background: #fff1c4; border-radius: 50%; width: 38px; height: 38px; font-size: 20px; margin-left: 6px; vertical-align: middle; animation: chipPulse 1.6s ease-in-out infinite; }

/* translated text (lang.js fx): takes the size of where it sits; fitTexts may make it smaller */
span.fx { font-size: inherit; }

