/* Tile faces: 36 kinds. Classic = drawn SVG, other themes = big emoji. */
const Tiles = (() => {
  const NUMS = ['一', '二', '三', '四', '五', '六', '七', '八', '九'];
  const B = '#1f5fbf', G = '#178a4a', R = '#d23a2c';

