  const ml = spec.mechLevel || o.level;      // (a set of levels may give its own level for ice and locks)
  if (o.mode !== 'level' || ml < Layouts.MECH.ice) return;
  const avoid = new Set([...(o.down || []), ...(o.gold || [])]);
