}
function updateObstacles() {
  if (!G || !G.ob) return;
  const ob = G.ob;
  for (const k of Object.keys(ob.need)) {
    const i = +k;
    if (!(ob.left[i] > 0)) continue;
    if (!G.alive[i]) { ob.left[i] = 0; continue; }                     // taken away by a joker
    let gone = 0; for (const j of G.inb[i]) if (!G.alive[j]) gone++;
