// ---------- daily tasks: 3 a day, each +1 star; all 3 open the chest ----------
// (texts in lang.js: task_<id>)
const TASK_TYPES = [
  { id: 'pairs', ico: '🀄', make: r => 20 + Math.floor(r() * 3) * 10 },
  { id: 'levels', ico: '🧩', make: r => 2 + Math.floor(r() * 2) },
