/* The dopamine moment: your row climbs past the people you just overtook. */
function showClimb(oldPts, newPts, then, mode = 'all') {
  const before = ranking(oldPts, mode), after = ranking(newPts, mode);
  const oldRank = before.findIndex(e => e.me) + 1, newRank = after.findIndex(e => e.me) + 1;
  const passed = after.slice(newRank, oldRank);          // the people you overtook (closest last)
  const above = after[newRank - 2];                       // the next target
  const show = passed.slice(-3);                          // animate at most 3 overtakes (fits on the screen)
  const rows = [...(above ? [above] : []), ...show];
  const RH = 46;
  const startIdx = (above ? 1 : 0) + show.length;         // where your row starts (below the others)
  const offset = passed.length - show.length;             // overtakes too far up to animate
  // rank shown on a row: before being overtaken it is one place higher than at the end
  const rankOf = (k, done) => {
    if (above && k === 0) return newRank - 1;
    const j = k - (above ? 1 : 0);
    const finalRank = newRank + offset + j + 1;
    return done ? finalRank : finalRank - 1;
  };
  openModal(`<h2>${tx(mode === 'week' ? 'climbWeek' : 'climbAll')}</h2>
    <div class="climb" style="height:${(rows.length + 1) * RH}px">
      ${rows.map((e, k) => `<div class="rrow crow${isFam(e) ? ' fam' : ''}" data-k="${k}" style="transform:translateY(${k * RH}px)">${rowHTML(e, rankOf(k, false), false, mode)}</div>`).join('')}
      <div class="rrow me crow" id="meRow" style="transform:translateY(${startIdx * RH}px)">${rowHTML(myEntry(oldPts, mode), oldRank, false, mode)}</div>
    </div>
    <div class="climb-msg" id="climbMsg">&nbsp;</div>
    <button class="big-btn play" id="clOk"><span class="bb-text"><b>${tx('next')}</b></span></button>`, false, null, 'compact');
  let stopped = false;   // tapping "Verder" early stops the animation cleanly
  $('#clOk').onclick = () => { stopped = true; closeModal(); then(); };
  const me = $('#meRow');
  const rowsEls = [...document.querySelectorAll('.crow[data-k]')];
  let pos = startIdx, k = 0;
  const steps = show.length;
  const stepTime = Math.max(380, Math.min(650, 2400 / Math.max(1, steps)));
  function step() {
    if (stopped) return;
    if (k >= steps) return finish();
    const victimIdx = startIdx - 1 - k;                  // the row right above you
    const victim = rowsEls[victimIdx];
    pos--; k++;
    me.style.transform = `translateY(${pos * RH}px) scale(1.04)`;
    victim.style.transform = `translateY(${(victimIdx + 1) * RH}px)`;
    victim.querySelector('.rk').textContent = medal(rankOf(victimIdx, true));
    const rank = oldRank - (passed.length - show.length) - k;
    me.querySelector('.rk').textContent = medal(rank);
    const pts = Math.round(oldPts + (newPts - oldPts) * k / steps);
    me.querySelector('.rp').textContent = mode === 'week' ? fmtN(pts) : tx('levelWord', pts);
    Sound.pass(k); buzz(15);
    const r = me.getBoundingClientRect(); FX.burst(r.left + r.width * 0.15, r.top + r.height / 2, 10);
    setTimeout(step, stepTime);
  }
  function finish() {
    if (stopped || !$('#climbMsg')) return;
    me.style.transform = `translateY(${pos * RH}px)`;
    me.querySelector('.rp').textContent = mode === 'week' ? fmtN(newPts) : tx('levelWord', newPts);
    me.querySelector('.rk').textContent = medal(newRank);
    me.classList.add('glow');
    Sound.rankUp(); FX.confetti(); buzz([30, 50, 30, 50, 60]);
    const n = passed.length;
    const who = n === 1 ? tx('passedOne', esc(passed[0].name)) : tx('passedMany', n);
    const gap = mode === 'week' ? tx('points', fmtN(above ? above.points - newPts + 1 : 0)) : (above ? tx('levelsN', above.level - newPts + 1) : '');
    const nxt = above ? `<br><small>${tx('gapTo', gap, above.avatar + ' ' + esc(above.name))}</small>` : `<br><small>${tx('onTop')}</small>`;
    const wk = mode === 'week' ? `<br><small>${tx('weekEnds', weekLeftText())}</small>` : '';
    $('#climbMsg').innerHTML = `<span class="climb-up">#${oldRank} → #${newRank} ⬆</span><br>${who}${nxt}${wk}`;
  }
  setTimeout(() => { if (!stopped) step(); }, 650);
}
/* Oma's Mahjong — hearts between family members, with an optional short message.
   hearts/<to>/<from> = { name, t }: t < 0 means "seen" (the receiver turns it negative).
   The message goes to plays/msg-<to> (see MSG in rules.js). Timings are in RULES.hearts. */
'use strict';

const sentToday = pid => S.heartsSent[pid] === todayKey();
const heartBtn = e => `<button class="heart-btn${sentToday(e.id) ? ' sent' : ''}" data-pid="${e.id}" data-name="${esc(e.name)}" aria-label="${tx('sendHeartLbl')}">${sentToday(e.id) ? '💛✓' : '💛'}</button>`;
const recent = t => Date.now() - Math.abs(t) <= RULES.hearts.showDays * 864e5;

// ---------- sending ----------
async function sendHeart(pid, name, btn) {
  if (!S.name) return askName(() => sendHeart(pid, name, btn));
  if (sentToday(pid)) { toast(tx('heartAlready', name)); return; }
  // pick a short message to go with it (or none): just tapping, no typing needed
  const quick = tx('quickMsgs', S.level);
  openModal(`<div class="heart-big sm">💛</div><h2>${tx('heartFor', esc(name))}</h2><p class="note small">${tx('heartMsgQ')}</p>
    <div class="msg-pick">${quick.map((m, i) => `<button class="mp" data-i="${i}">${esc(m)}</button>`).join('')}</div>
    <button class="big-btn play" id="hmNone"><span class="bb-text"><b>${tx('heartOnly')}</b></span></button>`, true);
  document.querySelectorAll('.msg-pick .mp').forEach(b => b.onclick = () => { closeModal(); doSendHeart(pid, name, btn, quick[+b.dataset.i]); });
  $('#hmNone').onclick = () => { closeModal(); doSendHeart(pid, name, btn, ''); };
}
async function doSendHeart(pid, name, btn, msg) {
  ensureId();
  try {
    const t = Date.now(), me = S.name.slice(0, 24);
    const r = await dbSend(`hearts/${pid}/${S.pid}`, { name: me, t });
    if (!r.ok) throw 0;
    if (msg) dbSend(`plays/${msgKey(pid)}`, { k: 'msg', t, from: S.pid, name: me, ...msgParts(msg) }, 'POST').catch(() => { });
    S.heartsSent[pid] = todayKey(); bumpStat('heartsSent');
    S.heartsOut[pid] = { t, seen: 0, name }; save();
    logEvt('heart_out', { to: name, msg: msg ? 1 : undefined });
    Sound.unlock(); buzz(20);
    if (btn) { btn.classList.add('sent'); btn.textContent = '💛✓'; }
    showHeartSent(name);
  } catch (e) { toast(tx('heartFail')); }
}
// a big, clear "it is on its way" moment for the sender
function showHeartSent(name) {
  Sound.trophy(); buzz([20, 40, 20, 40, 60]); heartRain();
  openModal(`<div class="heart-big">💛</div><h2>${tx('heartSent')}</h2>
    <p>${tx('heartSentText', esc(name))}</p>
    <p class="note small">${tx('heartSentNote')}</p>
    <button class="big-btn play" id="hsOk"><span class="bb-text"><b>${tx('nice')}</b></span></button>`, false);
  setTimeout(heartRain, 700);
  $('#hsOk').onclick = () => { closeModal(); if (curScreen === 'ranking') renderRanking(); };
}
// small status next to a family member: did they see my heart?
function heartState(pid) {
  const o = S.heartsOut[pid];
  if (!o || !recent(o.t)) return '';
  return o.seen ? `<small class="hs seen">${tx('heartSeenTag')}</small>` : `<small class="hs">${tx('heartOnWay')}</small>`;
}
// did the people I sent a heart to see it?
let sentCheckAt = 0;
async function checkSentHearts() {
  let changed = false;
  for (const [pid, o] of Object.entries(S.heartsOut)) {
    if (o.seen || !recent(o.t)) continue;
    try {
      const v = await dbGet(`hearts/${pid}/${S.pid}`);
      if (v && v.t < 0) { o.seen = Date.now(); changed = true; toast(tx('heartSeenToast', o.name), 3200); }
    } catch (e) { }
  }
  if (changed) save();
  return changed;
}

// ---------- receiving ----------
// tell the sender we saw it: the heart is stored again with a negative time
function markHeartsSeen(list) {
  ensureId();
  list.forEach(h => dbSend(`hearts/${S.pid}/${h.from}`, { name: h.name.slice(0, 24), t: -Math.abs(h.t) }).catch(() => { }));
}
// new hearts since last time (one request at a time, so a heart is never shown twice)
let heartsBusy = false;
async function fetchHearts() {
  if (!DB_URL || !S.pid || heartsBusy) return [];
  heartsBusy = true;
  try {
    const data = await dbGet(`hearts/${S.pid}`) || {};
    const fresh = Object.entries(data).filter(([from, v]) => v && v.t > (S.heartsSeen[from] || 0) && (S.pid.startsWith('test-') || !from.startsWith('test-')))
      .map(([from, v]) => ({ from, name: String(v.name || tx('someone')).slice(0, 24), t: v.t }));
    fresh.forEach(h => { S.heartsSeen[h.from] = h.t; });
    if (fresh.length) { await attachMsgs(fresh); bumpStat('hearts', fresh.length); save(); }
    return fresh;
  } catch (e) { return []; } finally { heartsBusy = false; }
}
// the message that came with a heart: same sender, sent at the same moment
async function attachMsgs(list) {
  try {
    const ms = Object.values(await dbGet(`plays/${msgKey(S.pid)}`) || {});
    list.forEach(h => { const m = ms.filter(m => m && m.from === h.from && Math.abs(m.t - h.t) < 120000).pop(); if (m && msgText(m)) h.msg = msgText(m).slice(0, MSG.max); });
  } catch (e) { }
}
const heartNames = list => [...new Set(list.map(h => h.name))];
const msgHTML = list => list.filter(h => h.msg).map(h => `<p class="heart-msg">“${esc(h.msg)}”<small>${esc(h.name)}</small></p>`).join('');
const logHeartIn = (list, where) => logEvt('heart_in', { from: heartNames(list).join(', '), where, msg: list.some(h => h.msg) ? 1 : undefined });
// at home: a big pop-up
function showHearts(list, then) {
  Sound.trophy(); buzz([20, 40, 20, 40, 40]);
  heartRain();
  const names = heartNames(list).map(esc);
  const who = names.length === 1 ? tx('heartFrom1', names[0]) : tx('heartFromMany', names.slice(0, -1).join(', '), names.slice(-1));
  openModal(`<div class="heart-big">💛</div><h2 class="heart-h">${tx('heartForYou')}</h2><p class="heart-who">${who}</p>${msgHTML(list)}
    <button class="big-btn play" id="hOk"><span class="bb-text"><b>${tx('howSweet')}</b></span></button>`, false);
  setTimeout(heartRain, 900); setTimeout(heartRain, 1900);
  markHeartsSeen(list); logHeartIn(list, 'popup');
  $('#hOk').onclick = () => { closeModal(); if (then) then(); };
}
// during a level: a short heart moment that closes by itself
function heartPop(list) {
  const names = heartNames(list).map(esc);
  let el = $('#heartPop');
  if (!el) { el = document.createElement('div'); el.id = 'heartPop'; document.body.appendChild(el); }
  el.innerHTML = `<div class="hp-card"><div class="hp-heart">💛</div><b>${names.join(' ' + tx('and') + ' ')}</b><span>${tx('sendsYou', names.length)}</span>${msgHTML(list)}<small>${tx('tapToPlay')}</small></div>`;
  el.className = 'on';
  Sound.trophy(); buzz([20, 40, 20, 40, 60]); heartRain(); setTimeout(heartRain, 900);
  markHeartsSeen(list); logHeartIn(list, 'level');
  const close = () => { el.className = ''; clearTimeout(el._t); };
  el.onclick = close; clearTimeout(el._t);
  el._t = setTimeout(close, list.some(h => h.msg) ? RULES.hearts.popupWithMsgMs : RULES.hearts.popupMs);
}
// hearts fountain up from the bottom of the screen, so the words stay readable
function heartRain() { [0.08, 0.3, 0.7, 0.92].forEach((f, i) => setTimeout(() => FX.emoji(innerWidth * f, innerHeight - 20, ['💛', '💖', '💛', '✨'], 12), i * 120)); }
async function checkHearts() {
  const fresh = await fetchHearts();
  if (fresh.length) deliverHearts(fresh);
}
// show new hearts right away: a big pop-up at home, a short heart moment during a level, later otherwise
function deliverHearts(fresh) {
  const free = modalFree();
  if (free && curScreen === 'home') showHearts(fresh, () => renderHome());
  else if (free) heartPop(fresh);
  else { S.pendingHearts = S.pendingHearts.concat(fresh); save(); }
}
// live: the database tells us the moment someone sends a heart
let heartStream = null;
function startHeartStream() {
  if (heartStream || !DB_URL || !S.pid || typeof EventSource === 'undefined') return;
  try {
    heartStream = new EventSource(dbUrl(`hearts/${S.pid}`));
    let t = 0;
    const ping = () => { clearTimeout(t); t = setTimeout(checkHearts, 400); };
    heartStream.addEventListener('put', ping);
    heartStream.addEventListener('patch', ping);
  } catch (e) { heartStream = null; }
}
